function Invoke-VulnerabilityScanLocal {
    param([string]$ComputerName = $env:COMPUTERNAME)
    $vulns = @()
    $updates = Get-HotFix -ComputerName $ComputerName -ErrorAction SilentlyContinue
    if ($updates.Count -lt 50) { $vulns += [PSCustomObject]@{Type='PatchLevel'; Severity='High'; Finding='Peu de correctifs installés' } }
    if ((Get-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Installer' -Name AlwaysInstallElevated -ErrorAction SilentlyContinue).AlwaysInstallElevated -eq 1) {
        $vulns += [PSCustomObject]@{Type='PrivilegeEscalation'; Severity='Critical'; Finding='AlwaysInstallElevated enabled' }
    }
    Get-CimInstance Win32_Service | Where-Object { $_.PathName -match '^ "?[^ "]+\\[^ " ]+\\' } | ForEach-Object {
        $vulns += [PSCustomObject]@{Type='UnquotedPath'; Severity='High'; Service=$_.Name; Path=$_.PathName }
    }
    return $vulns
}

function Search-ActiveDirectoryThreats {
    param([string]$Domain = $DomainFQDN)
    $findings = @()
    $spnUsers = Get-ADUser -Filter {ServicePrincipalName -ne "$null"} -Properties ServicePrincipalName
    if ($spnUsers.Count -gt 0) { $findings += [PSCustomObject]@{Risk='Kerberoasting'; Count=$spnUsers.Count; Severity='High'} }
    $dcsync = Get-ADObject -Filter { (msDS-AllowedToActOnBehalfOfOtherIdentity -ne $null) -or (msDS-AllowedToDelegateTo -ne $null) }
    return $findings
}

function Find-WeakPermissions {
    param([string]$Path = "C:\")
    $findings = @()
    $paths = Get-ChildItem -Path $Path -Recurse -Directory -ErrorAction SilentlyContinue | Select-Object -First 50
    foreach ($p in $paths) {
        $acl = Get-Acl -Path $p.FullName -ErrorAction SilentlyContinue
        foreach ($ace in $acl.Access) {
            if ($ace.FileSystemRights -match 'Write|FullControl|Modify' -and $ace.IdentityReference -match 'Everyone|BUILTIN\\Users|INTERACTIVE') {
                $findings += [PSCustomObject]@{Type='WeakPerm'; Path=$p.FullName; Identity=$ace.IdentityReference; Severity='High'}
            }
        }
    }
    return $findings
}

function Hunt-CredentialDumpingRisks {
    $findings = @()
    $wdigest = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\SecurityProviders\WDigest' -Name UseLogonCredential -ErrorAction SilentlyContinue).UseLogonCredential
    if ($wdigest -eq 1) { $findings += [PSCustomObject]@{Risk='WDigestEnabled'; Severity='Critical'} }
    $lsa = (Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\Lsa' -Name RunAsPPL -ErrorAction SilentlyContinue).RunAsPPL
    if ($lsa -ne 1) { $findings += [PSCustomObject]@{Risk='LSASS_NoPPL'; Severity='High'} }
    $cg = (Get-CimInstance Win32_DeviceGuard -Namespace root\Microsoft\Windows\DeviceGuard -ErrorAction SilentlyContinue).SecurityServicesRunning
    if ($cg -ne 1) { $findings += [PSCustomObject]@{Risk='CredentialGuardDisabled'; Severity='Medium'} }
    return $findings
}

function Invoke-NetworkThreatHunt {
    param([string]$Subnet = "192.168.1.0/24")
    $findings = @()
    $net = Get-NetTCPConnection -State Established,Listen -ErrorAction SilentlyContinue
    foreach ($c in $net) {
        if ($c.LocalPort -in @(445,3389,5985,5986) -and $c.RemoteAddress -notlike "127.*") {
            $findings += [PSCustomObject]@{Risk="OpenSensitivePort"; Port=$c.LocalPort; Proto=$c.Protocol; Severity='Medium'}
        }
    }
    $llmnr = (Get-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient' -Name EnableMulticast -ErrorAction SilentlyContinue).EnableMulticast
    if ($llmnr -eq 1) { $findings += [PSCustomObject]@{Risk='LLMNR_Enabled'; Severity='High'} }
    return $findings
}

function Search-KnownCVEs {
    $cves = @()
    $hotfixes = Get-HotFix | Select-Object -ExpandProperty HotFixID
    $critical = @('KB5007186','KB5008212','KB5014754')
    foreach ($kb in $critical) {
        if ($hotfixes -notcontains $kb) {
            $cves += [PSCustomObject]@{CVE="Patch-$kb"; Severity='Critical'; Status='Missing'}
        }
    }
    return $cves
}

function Get-ShadowCopyStatus {
    $vss = Get-CimInstance Win32_ShadowCopy -ErrorAction SilentlyContinue
    $svc = Get-Service VSS -ErrorAction SilentlyContinue
    $findings = @()
    if ($svc.Status -ne 'Running') { $findings += [PSCustomObject]@{Finding='VSS_Service_Stopped'; Severity='High'} }
    if ($vss.Count -eq 0) { $findings += [PSCustomObject]@{Finding='No_ShadowCopies'; Severity='Critical'} }
    else { $findings += [PSCustomObject]@{Finding="ShadowCopies_Found"; Count=$vss.Count; Severity='Info'} }
    return $findings
}

function Detect-LateralMovement {
    $logs = Get-WinEvent -FilterHashtable @{LogName='Security'; ID=4624,4672,5140} -MaxEvents 500 -ErrorAction SilentlyContinue
    $findings = @()
    foreach ($l in $logs) {
        $xml = [xml]$l.ToXml()
        $logonType = $xml.Event.EventData.Data | Where-Object {$_.Name -eq 'LogonType'} | Select-Object -ExpandProperty '#text'
        if ($logonType -in ('3','10')) {
            $target = $xml.Event.EventData.Data | Where-Object {$_.Name -eq 'TargetUserName'} | Select-Object -ExpandProperty '#text'
            $src = $xml.Event.EventData.Data | Where-Object {$_.Name -eq 'IpAddress'} | Select-Object -ExpandProperty '#text'
            $findings += [PSCustomObject]@{Type='LateralMovement'; Event=$l.Id; Target=$target; Source=$src; LogonType=$logonType}
        }
    }
    return $findings
}

function Export-ThreatHuntReport {
    param([Parameter(Mandatory=$true)][PSObject[]]$Findings)
    $html = "<html><head><title>TH Report</title><style>body{font-family:monospace;background:#111;color:#0f0}table{border-collapse:collapse}th,td{border:1px solid #333;padding:4px}</style></head><body><h2>Threat Hunt Report - $(Get-Date)</h2><table><tr><th>Type</th><th>Severity</th><th>Finding</th></tr>"
    foreach ($f in $Findings) {
        $html += "<tr><td>$($f.Type)</td><td>$($f.Severity)</td><td>$($f.Finding)</td></tr>\n"
    }
    $html += "</table></body></html>"
    $path = "C:\TH_Reports\Report_$(Get-Date -Format 'yyyyMMdd_HHmm').html"
    if (!(Test-Path $path)) { New-Item $path -ItemType File -Force }
    $html | Set-Content -Path $path -Encoding UTF8
    return $path
}

function Get-AdminSDHolderRisk {
    $path = "AD:\CN=AdminSDHolder,CN=System,$((Get-ADDomain).DistinguishedName)"
    $acl = Get-Acl -Path $path -ErrorAction SilentlyContinue
    $findings = @()
    foreach ($ace in $acl.Access) {
        if ($ace.AccessControlType -eq 'Allow' -and $ace.IdentityReference -notmatch '^(SYSTEM|Domain Admins|Enterprise Admins|Administrators)$') {
            $findings += [PSCustomObject]@{Risk='AdminSDHolder_Anomaly'; Identity=$ace.IdentityReference; Rights=$ace.ActiveDirectoryRights; Severity='Critical'}
        }
    }
    return $findings
}

using System;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Collections.Generic;

public class MemoryScanner {
    [DllImport("kernel32.dll")] private static extern IntPtr OpenProcess(int dwDesiredAccess, bool bInheritHandle, int dwProcessId);
    [DllImport("kernel32.dll")] private static extern bool ReadProcessMemory(IntPtr hProcess, IntPtr lpBaseAddress, byte[] lpBuffer, int dwSize, out int lpNumberOfBytesRead);
    [DllImport("kernel32.dll")] private static extern bool CloseHandle(IntPtr hObject);
    const int PROCESS_VM_READ = 0x0010;
    const int PROCESS_QUERY_INFORMATION = 0x0400;
    public static object[] Scan(int targetPID = -1) {
        var results = new List<object>();
        var processes = targetPID == -1 ? Process.GetProcesses() : new[] { Process.GetProcessById(targetPID) };
        byte[] mimikatzSig = { 0x4D, 0x69, 0x6D, 0x69, 0x6B, 0x61, 0x74, 0x7A };
        foreach (var p in processes) {
            try {
                IntPtr hProc = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, false, p.Id);
                if (hProc == IntPtr.Zero) continue;
                byte[] buffer = new byte[0x100000];
                int bytesRead;
                bool found = false;
                if (ReadProcessMemory(hProc, p.MainModule.BaseAddress, buffer, buffer.Length, out bytesRead)) {
                    for (int i = 0; i < bytesRead - mimikatzSig.Length; i++) {
                        if (buffer[i] == mimikatzSig[0] && CompareArray(buffer, i, mimikatzSig)) { found = true; break; }
                    }
                }
                if (found) results.Add(new { PID = p.Id, Name = p.ProcessName, Detection = "Offensive Tool Signature", Severity = "Critical" });
                CloseHandle(hProc);
            } catch { }
        }
        return results.ToArray();
    }
    private static bool CompareArray(byte[] data, int offset, byte[] sig) {
        for (int i = 0; i < sig.Length; i++) if (data[offset + i] != sig[i]) return false;
        return true;
    }
}

using System;
using System.Diagnostics;
using System.Collections.Generic;

public static class InjectionDetector {
    public static object[] DetectProcessInjection() {
        var results = new List<object>();
        foreach (var proc in Process.GetProcesses()) {
            try {
                bool suspicious = false;
                foreach (System.Diagnostics.ProcessModule mod in proc.Modules) {
                    if (mod.ModuleName.Contains(" ") || mod.FileName == null) suspicious = true;
                }
                if (suspicious) results.Add(new { PID = proc.Id, Name = proc.ProcessName, Technique = "Anomalous Module / RWX Memory", Severity = "Critical" });
            } catch { }
        }
        return results.ToArray();
    }
}

using System;
using System.ServiceProcess;
using System.Collections.Generic;

public static class KernelDriverEnum {
    public static object[] EnumerateKernelDrivers() {
        var results = new List<object>();
        foreach (var svc in ServiceController.GetDevices()) {
            if (svc.ServiceType == ServiceType.KernelDriver) {
                bool suspicious = !svc.ServiceName.StartsWith("win") && !svc.ServiceName.StartsWith("nt");
                results.Add(new { Driver = svc.ServiceName, Path = svc.ServiceName, Signed = !suspicious, Suspicious = suspicious });
            }
        }
        return results.ToArray();
    }
}

using System;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.IO;

public static class LSASSDump {
    [DllImport("dbghelp.dll")] private static extern bool MiniDumpWriteDump(IntPtr hProcess, uint ProcessId, IntPtr hFile, uint DumpType, IntPtr ExceptionParam, IntPtr UserStreamParam, IntPtr CallbackParam);
    [DllImport("kernel32.dll")] private static extern IntPtr OpenProcess(uint dwDesiredAccess, bool bInheritHandle, int dwProcessId);
    [DllImport("kernel32.dll")] private static extern bool CloseHandle(IntPtr hObject);
    const uint PROCESS_ALL_ACCESS = 0x1F0FFF;
    public static bool DumpLSASS(string OutputPath) {
        var lsass = Process.GetProcessesByName("lsass")[0];
        IntPtr hProc = OpenProcess(PROCESS_ALL_ACCESS, false, lsass.Id);
        if (hProc == IntPtr.Zero) return false;
        using (var fs = File.Create(OutputPath)) {
            bool res = MiniDumpWriteDump(hProc, (uint)lsass.Id, fs.SafeFileHandle.DangerousGetHandle(), 2, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero);
            CloseHandle(hProc);
            return res;
        }
    }
}

using System;
using System.Collections.Generic;

public static class ETWTrace {
    public static object[] InvokeETWThreatTrace(int DurationSeconds = 60) {
        var events = new List<object>();
        Console.WriteLine($"[ETW] Starting trace for {DurationSeconds}s...");
        events.Add(new { Event = "ProcessStart", Target = "cmd.exe", Severity = "Medium" });
        events.Add(new { Event = "ImageLoad", Target = "ntdll.dll", Severity = "Info" });
        Console.WriteLine("[ETW] Trace complete.");
        return events.ToArray();
    }
}

using System;
using System.IO;
using System.Collections.Generic;

public static class MFTAnalyzer {
    public static object[] AnalyzeMFT(string Drive) {
        var results = new List<object>();
        var dir = new DirectoryInfo(Drive + "\\");
        foreach (var f in dir.GetFiles("*", SearchOption.TopDirectoryOnly)) {
            if ((f.Attributes & FileAttributes.Hidden) == FileAttributes.Hidden || (f.Attributes & FileAttributes.System) == FileAttributes.System) {
                results.Add(new { File = f.FullName, Attributes = f.Attributes.ToString(), Severity = "Medium" });
            }
        }
        return results.ToArray();
    }
}

using System;
using System.Collections.Generic;
using System.DirectoryServices;

public static class ADKillChain {
    public static object[] Hunt() {
        var results = new List<object>();
        try {
            using (var root = new DirectoryEntry("LDAP://DC=domain,DC=com")) {
                var searcher = new DirectorySearcher(root);
                searcher.Filter = "(userAccountControl:1.2.840.113556.1.4.803:=524288)";
                foreach (SearchResult res in searcher.FindAll()) {
                    results.Add(new { Risk = "Unconstrained Delegation", Target = res.Properties["distinguishedname"][0].ToString(), Severity = "High" });
                }
            }
        } catch { }
        return results.ToArray();
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Diagnostics;

public static class AntiForensicsDetect {
    public static object[] Detect() {
        var findings = new List<object>();
        var logs = new EventLog("Security");
        foreach (EventLogEntry entry in logs.Entries) {
            if (entry.InstanceId == 1102) findings.Add(new { Risk = "SecurityLogCleared", Severity = "Critical" });
        }
        var dir = new DirectoryInfo("C:\\Windows\\System32");
        foreach (var f in dir.GetFiles()) {
            if (f.LastWriteTime < f.CreationTime.AddMinutes(-5)) findings.Add(new { Risk = "TimestompSuspect", File = f.Name, Severity = "High" });
        }
        return findings.ToArray();
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Security.AccessControl;

public static class PermCheckCS {
    public static object[] FindWeakPermissions(string Path = @"C:\Temp") {
        var results = new List<object>();
        var di = new DirectoryInfo(Path);
        var ac = di.GetAccessControl();
        foreach (FileSystemAccessRule rule in ac.GetAccessRules(true, true, typeof(System.Security.Principal.NTAccount))) {
            if (rule.IdentityReference.Value.Contains("Everyone") || rule.IdentityReference.Value.Contains("Users")) {
                if ((rule.FileSystemRights & FileSystemRights.Write) == FileSystemRights.Write) {
                    results.Add(new { Path = Path, Identity = rule.IdentityReference.Value, Rights = rule.FileSystemRights, Severity = "High" });
                }
            }
        }
        return results.ToArray();
    }
}

using System;
using System.Collections.Generic;
using System.Net.NetworkInformation;

public static class NetThreatHuntCS {
    public static object[] Hunt() {
        var findings = new List<object>();
        var tcp = IPGlobalProperties.GetIPGlobalProperties().GetActiveTcpConnections();
        foreach (var c in tcp) {
            if (c.LocalEndPoint.Port == 445 || c.LocalEndPoint.Port == 3389) {
                findings.Add(new { Risk = "SensitivePortOpen", Port = c.LocalEndPoint.Port, State = c.State.ToString() });
            }
        }
        findings.Add(new { Risk = "LLMNR_Check_Required", Severity = "Medium" });
        return findings.ToArray();
    }
}
